/* Health (D12, D13 — r&d/specs/health-page-spec.md): a summary row whose tiles
   scroll to their cards, then the body cards (viewBody, unchanged), then the
   calculators that use this data. Reads the same stores; stores nothing new. */
function healthSummary() {
  const sg = (v, unit) => v == null ? '' : `${v > 0 ? '▲' : v < 0 ? '▼' : '±'} ${nice(Math.abs(v))}${unit}`;
  // bodyweight: the 7-day average and its change over a week
  const { avg } = bwSeries(), a = avg[avg.length - 1];
  const a7 = a ? avgOn(avg, addDaysISO(a.date, -7)) : null;
  const bw = a ? { v: wt(a.v), d: a7 && a7.date !== a.date ? `${sg(dw(a.v - a7.v), U())} / 7 d` : '7-day avg' } : null;
  // body fat: newest complete test, against the one before it of the same method
  const tests = [...(S.calipers || [])].sort((x, y) => x.date < y.date ? 1 : -1)
    .map(t => ({ t, r: caliperCalc(t) })).filter(x => x.r && x.r.complete);
  const t0 = tests[0], t1 = t0 && tests.slice(1).find(x => x.t.method === t0.t.method);
  const bf = t0 ? { v: `${t0.r.bf.toFixed(1)}%`, d: `${Math.round(t0.r.sum)} mm${t1 ? ` · ${sg(+(t0.r.bf - t1.r.bf).toFixed(1), '%')}` : ''}` } : null;
  // waist, or else whichever site was measured last
  const ser = measSeries();
  const site = ser.waist ? 'waist' : Object.keys(ser).sort((x, y) => ser[x].slice(-1)[0].date < ser[y].slice(-1)[0].date ? 1 : -1)[0];
  const ms = site ? ser[site] : null, m0 = ms && ms[ms.length - 1], m1 = ms && ms[ms.length - 2];
  const meas = m0 ? { k: measLabel(site), v: `${nice(dlen(m0.v))}${lenU()}`, d: m1 ? sg(+dlen(m0.v - m1.v).toFixed(1), lenU()) : esc(relDay(m0.date)) } : null;
  const tile = (target, k, x, empty) => `<button class="stat" data-hl="${target}" aria-label="${esc(k)}: ${x ? esc(x.v) : esc(empty)} — open" style="text-align:left;cursor:pointer;font:inherit;color:inherit">
    <div class="k">${esc(k)}</div><div class="v" style="font-size:18px">${x ? x.v : '—'}</div><div class="d">${x ? x.d : esc(empty)}</div></button>`;
  return `<div class="stats grid3" style="margin-bottom:13px">
    ${tile('hlBw', 'Bodyweight', bw, 'No weigh-ins')}
    ${tile('hlBf', 'Body fat', bf, 'No tests')}
    ${tile('hlMeas', meas ? meas.k : 'Waist', meas, 'No measurements')}
  </div>`;
}
export function viewHealth() {
  return `
  <h1>Health</h1>
  <div class="sub" style="margin-bottom:14px">Bodyweight, body fat, measurements and photos — kept on this phone.</div>
  ${healthSummary()}
  ${viewBody()}
  ${bpCard()}
  ${gluCard()}
  ${fitCard()}
  ${mobTestsCard()}
  <div class="card" style="margin-bottom:13px">
    <div class="eyebrow" style="margin-bottom:6px">Physique</div>
    <div class="sub" style="margin-bottom:8px">Calculators that start from the numbers above. Estimates — see the notes in each.</div>
    <div class="row" style="gap:8px"><button class="btn sm grow" data-tool="ffmi">FFMI</button><button class="btn sm grow" data-tool="potential">Max muscular potential</button></div>
  </div>
  <button class="btn wide ghost" id="hlRecovery" style="margin-bottom:13px">Recovery map — on Stats → Muscles</button>`;
}

/* ---------------- check-in modal ---------------- */
export function openCheckin(date = today()) {
  const c = checkinFor(date) || {};
  const rate = (key, val) => `<div class="rate" data-rate="${key}">` +
    [1, 2, 3, 4, 5].map(n => `<button type="button" data-v="${n}" class="${val === n ? 'on' : ''}">${n}</button>`).join('') + `</div>`;
  modal({
    title: `Check-in · ${fmtDate(date)}`,
    body: `
      <div class="grid2">
        <div class="field"><label>Bodyweight (${U()})</label>
          <input type="number" step="0.1" inputmode="decimal" id="ciW" value="${c.weight ? dw(c.weight) : ''}" placeholder="—"></div>
        <div class="field"><label>Sleep (hours)</label>
          <input type="number" step="0.25" inputmode="decimal" id="ciSH" value="${c.sleepH ?? ''}" placeholder="—"></div>
      </div>
      <div class="field"><label>Sleep quality</label>${rate('sleepQ', c.sleepQ)}</div>
      <div class="field"><label>Energy / readiness</label>${rate('energy', c.energy)}</div>
      <div class="field"><label>Soreness</label>${rate('soreness', c.soreness)}</div>
      <div class="field"><label>Stress</label>${rate('stress', c.stress)}</div>
      <div class="field"><label>Notes</label>
        <textarea id="ciNotes" rows="2" placeholder="How you feel, niggles, plans…">${esc(c.notes || '')}</textarea></div>
    `,
    foot: `${checkinFor(date) ? '<button class="btn danger" id="ciDel">Delete</button>' : ''}<button class="btn primary" id="ciSave">Save check-in</button>`,
    onOpen: bg => {
      const picked = { sleepQ: c.sleepQ, energy: c.energy, soreness: c.soreness, stress: c.stress };
      bg.querySelectorAll('[data-rate]').forEach(g => {
        g.addEventListener('click', e => {
          const b = e.target.closest('button'); if (!b) return;
          const k = g.dataset.rate, v = +b.dataset.v;
          picked[k] = picked[k] === v ? undefined : v;
          g.querySelectorAll('button').forEach(x => x.classList.toggle('on', +x.dataset.v === picked[k]));
        });
      });
      const del = $('#ciDel', bg);
      if (del) del.onclick = () => { S.checkins = S.checkins.filter(x => x.date !== date); save(); closeModal(); render(); toast('Check-in deleted'); };
      $('#ciSave', bg).onclick = () => {
        const rec = {
          date,
          weight: $('#ciW', bg).value ? toKg(+$('#ciW', bg).value) : 0,
          sleepH: $('#ciSH', bg).value ? +$('#ciSH', bg).value : null,
          kcal: c.kcal ?? null,   // no longer entered (food left in 0.25.0); an old value is kept, not wiped
          notes: $('#ciNotes', bg).value.trim(),
          ...picked,
          mt: Date.now(),   // when it was last saved, so an edit on one phone reaches the others (Drive sync)
        };
        S.checkins = S.checkins.filter(x => x.date !== date);
        S.checkins.push(rec);
        save(); closeModal(); render();
        toast('Check-in saved', 'green');
      };
    },
  });
}

/* ---------------- goal modal ---------------- */
export function openGoal(id) {
  const g = S.goals.find(x => x.id === id) || { id: uid(), type: 'lift', name: '', exercise: priorityKeys()[0], target: '', deadline: '' };
  const exList = allExercises().filter(x => categoryOf(x.leaf) !== 'Cardio');   // a 1RM goal needs a lift
  modal({
    title: id ? 'Edit goal' : 'New goal',
    body: `
      <div class="field"><label>Type</label>
        <select id="gType">
          <option value="lift"${g.type === 'lift' ? ' selected' : ''}>Lift 1RM</option>
          <option value="total"${g.type === 'total' ? ' selected' : ''}>Powerlifting total</option>
          <option value="bodyweight"${g.type === 'bodyweight' ? ' selected' : ''}>Bodyweight</option>
          <option value="sessions"${g.type === 'sessions' ? ' selected' : ''}>Sessions completed</option>
          <option value="custom"${g.type === 'custom' ? ' selected' : ''}>Custom (manual)</option>
        </select></div>
      <div class="field" id="gExWrap"><label>Exercise</label>
        <select id="gEx">${exOptionsHtml(exList, g.exercise, priorityKeys())}</select></div>
      <div class="field"><label>Goal name</label>
        <input id="gName" value="${esc(g.name)}" placeholder="e.g. 200kg squat"></div>
      <div class="grid2">
        <div class="field"><label>Starting value</label>
          <input type="number" step="0.5" inputmode="decimal" id="gStart" value="${g.startVal != null ? (g.type === 'sessions' ? g.startVal : dw(g.startVal)) : ''}" placeholder="auto"></div>
        <div class="field"><label>Target</label>
          <input type="number" step="0.5" inputmode="decimal" id="gTarget" value="${g.target ? (g.type === 'sessions' ? g.target : dw(g.target)) : ''}"></div>
      </div>
      <div class="field" id="gCurWrap"><label>Current value</label>
        <input type="number" step="0.5" inputmode="decimal" id="gCur" value="${g.current ? dw(g.current) : ''}" placeholder="update as you go"></div>
      <div class="field"><label>Deadline (optional)</label>
        <input type="date" id="gDead" value="${g.deadline || ''}"></div>
    `,
    foot: `${id ? '<button class="btn danger" id="gDel">Delete</button>' : ''}<button class="btn primary" id="gSave">Save goal</button>`,
    onOpen: bg => {
      const sync = () => {
        const t = $('#gType', bg).value;
        $('#gExWrap', bg).style.display = t === 'lift' ? '' : 'none';
        $('#gCurWrap', bg).style.display = t === 'custom' ? '' : 'none';
      };
      $('#gType', bg).onchange = sync; sync();
      const del = $('#gDel', bg);
      if (del) del.onclick = () => { S.goals = S.goals.filter(x => x.id !== id); save(); closeModal(); render(); };
      $('#gSave', bg).onclick = () => {
        const type = $('#gType', bg).value;
        const isCount = type === 'sessions';
        const ex = $('#gEx', bg).value;
        const target = +$('#gTarget', bg).value;
        if (!target) return toast('Set a target');
        const startRaw = $('#gStart', bg).value;
        const rec = {
          id: g.id, type, exercise: ex,
          name: $('#gName', bg).value.trim() || (type === 'lift' ? `${ex} ${nice(target)}${U()}` : type === 'total' ? `${nice(target)}${U()} total` : type === 'bodyweight' ? `${nice(target)}${U()} bodyweight` : type === 'sessions' ? `${target} sessions` : 'Goal'),
          target: isCount ? target : toKg(target),
          deadline: $('#gDead', bg).value || '',
          since: g.since || today(),
        };
        if (type === 'custom') {
          const curRaw = $('#gCur', bg).value;
          rec.current = curRaw !== '' ? toKg(+curRaw) : (g.current || 0);
        }
        rec.startVal = startRaw !== '' ? (isCount ? +startRaw : toKg(+startRaw)) : (g.startVal ?? goalCurrent(rec));
        S.goals = S.goals.filter(x => x.id !== g.id);
        S.goals.push(rec);
        save(); closeModal(); render(); toast('Goal saved', 'green');
      };
    },
  });
}

