        const rows = (T.sides ? ['L', 'R'] : [null]).map(sd => ({ sd, v: read(sd) })).filter(x => x.v != null);
        if (!rows.length) return toast('Enter a result');
        S.mobTests = S.mobTests || [];
        rows.forEach(x => S.mobTests.push({ id: uid(), date, test, side: x.sd, v: x.v, mt: Date.now() }));
        mobTestPick = test;
