  const pick = fitPick(L.sets, T);
  if (!pick || !(bw > 0)) return null;
  const raw = STD[P.std], fem = t.sex === 'female', th = raw.slice(0, 5).map(x => x * (fem ? raw[5] : 1));
  const judged = pick.e1 / bw / V.factor;
