    T.step('Judged', `${nice(dw(pick.e1))} ÷ ${nice(dw(bw))} ÷ ${V.factor.toFixed(2)} = ${judged.toFixed(3)}× bw`, 'e1RM ÷ bodyweight ÷ variation factor');
