    v = +g.sec; text = `${nice(v)} s`;
    if (T) T.step(g.mode === 'hang' ? 'Dead hang (the fallback)' : 'Bodyweight bar hold', `${nice(v)} s`, g.mode === 'hang' ? 'scored on the bar-hold cutoffs — not like for like' : '');
