  const byPct = [...strength].sort((a, b) => b.pctInt - a.pctInt);
  const strongest = strength.length >= 2 ? byPct[0] : null, lagging = strength.length >= 2 ? byPct[byPct.length - 1] : null;
  const pool = [...others.map(o => ({ label: o.label, score: o.score, k: 0, pct: 0 })), ...strength.map(s => ({ label: s.label, score: s.score, k: 1, pct: s.pctInt }))];
  const weakest = pool.length ? pool.reduce((a, b) => b.score < a.score || (b.score === a.score && (b.k < a.k || (b.k === a.k && b.pct < a.pct))) ? b : a) : null;
  const bits = [];
  if (strongest) bits.push(`${strongest.label}-dominant, lagging ${lagging.label.toLowerCase()}`);
  if (tol) bits.push(`${tol.word} volume tolerance`);
  if (weakest) bits.push(`work on ${weakest.label.toLowerCase()}`);
  const type = bits.length ? bits.join('; ').replace(/^./, c => c.toUpperCase()) : '';
