const FIT_STEPS = { home: ['intro', 'home', 'results'], full: ['intro', 'home', 'power', 'ladder', 'tol', 'grip', 'engine', 'results'] };
const FIT_STEP_LABEL = { intro: 'Start', home: 'Home screen', power: 'Power', ladder: 'Rep ladder', tol: 'Rep tolerance', grip: 'Grip', engine: 'Engine', results: 'Results' };
function fitGet(o, path) { return path.split('.').reduce((a, k) => a == null ? a : a[k], o); }
