      <div class="grid2" style="gap:8px;margin:6px 0 12px">${fitInput(D, 'home.scratch.L', 'Left on top', { step: 0.5 })}${fitInput(D, 'home.scratch.R', 'Right on top', { step: 0.5 })}</div>
